export const ASSET_CODES = ['512890', '513100', '588000', '518880', '511010'] as const;
export type AssetCode = (typeof ASSET_CODES)[number];

export interface PublicAsset {
  code: AssetCode;
  name: string;
  assetClass: 'EQUITY' | 'GOLD' | 'BOND';
  role: string;
  latestPrice: number;
  lotSize: number;
  strategicWeight: number;
  return63: number | null;
  return126: number | null;
  return252: number | null;
  trendScore: number | null;
  vol20: number | null;
  vol60: number | null;
  forecastVol: number | null;
  relativeStrength: number | null;
  volPenalty: number | null;
  confirmedSignals: {
    trendScore: number | null;
    relativeStrength: number | null;
    volPenalty: number | null;
  };
  targetFormation: {
    group: 'EQUITY' | 'DEFENSE';
    strategicGroupShare: number;
    attractiveness: number | null;
    finalGroupShare: number;
    floor: number;
    cap: number;
    boundScope: 'EQUITY_INTERNAL' | 'PORTFOLIO';
  };
  confirmedTarget: number;
  provisionalTarget: number;
}

export interface StrategyMetrics {
  cagr: number | null;
  annualVolatility: number | null;
  maxDrawdown: number | null;
  sharpe: number | null;
  sortino: number | null;
  calmar: number | null;
  worstMonth: number | null;
  worstYear: number | null;
  rolling3YCagrMin: number | null;
  turnover: number | null;
  tradeCount: number | null;
  recoveryDays: number | null;
  timeUnderWater: number | null;
}

export interface RiskDiagnostics {
  asOf: string;
  windowDays: number;
  portfolioAnnualVolatility: number;
  riskContributions: Array<{
    code: AssetCode;
    weight: number;
    componentVolatility: number;
    share: number;
  }>;
  correlation: Record<AssetCode, Record<AssetCode, number>>;
  averagePairCorrelation: number;
  averageEquityCorrelation: number;
  changeSincePreviousConfirmation: {
    previousDate: string;
    riskScore: number;
    equityTarget: number;
    drawdown: number;
  };
  method: string;
}

export interface MarketBar {
  date: string;
  open: number | null;
  high: number | null;
  low: number | null;
  close: number;
  volume: number | null;
  amount: number | null;
}

export interface MarketSeriesBundle {
  schemaVersion: string;
  generatedAt: string;
  historyTradingDays: number;
  assets: Record<AssetCode, {
    source: string;
    priceConvention: string;
    volumeUnit: string;
    hasVolume: boolean;
    bars: MarketBar[];
  }>;
}

export interface PublicSnapshot {
  meta: {
    schemaVersion: string;
    webVersion: string;
    strategyVersion: string;
    generatedAt: string;
    signalDate: string;
    confirmedSignalDate: string;
    confirmedEffectiveDate: string;
    targetStatus: string;
    configFingerprint: string;
    priceConvention: string;
    timingRule: string;
  };
  health: {
    status: string;
    blocking: boolean;
    summary: string;
    issues: Array<{ type: string; label: string; severity: string; code: string; details: string }>;
  };
  provenance: Record<string, {
    source: string;
    fetchedAt?: string;
    firstDate?: string;
    lastDate?: string;
    observations?: string;
    durationMs?: number;
    calendarFillCount?: number;
    calendarFilledDates?: string[];
  }>;
  allocationModel: {
    baseEquityTotal: number;
    coreRatio: number;
    equityMin: number;
    equityMax: number;
    riskWeights: { trend: number; volatility: number; drawdown: number };
    attractivenessWeights: { trend: number; relativeStrength: number; volPenalty: number };
    equityBounds: Record<string, { floor: number; cap: number }>;
    defense: {
      goldBaseShare: number;
      goldTrendCoefficient: number;
      bondTrendCoefficient: number;
      goldShareMin: number;
      goldShareMax: number;
      goldAbsoluteMin: number;
      goldAbsoluteMax: number;
      bondAbsoluteMin: number;
      bondAbsoluteMax: number;
    };
  };
  timingAudit: {
    status: string;
    signalAtClose: boolean;
    positionShiftTradingDays: number;
    monthEndOnly: boolean;
    adjustedPriceOnly: boolean;
    premiumGateSeparated: boolean;
  };
  executionModel: {
    premiumGate: {
      halfBuyThreshold: number;
      blockBuyThreshold: number;
      redWarningThreshold: number;
      halfBuyFactor: number;
    };
    rebalance: { absoluteBand: number; relativeBand: number; partialFactor: number };
    freshness: { snapshotMaxAgeHours: number; holdingsMaxAgeDays: number; premiumMaxAgeHours: number };
    defaultLotSize: number;
    cashFlowFirst: boolean;
  };
  risk: {
    score: number;
    regime: 'GREEN' | 'YELLOW' | 'ORANGE' | 'RED' | 'DATA ERROR';
    trendBreadth: number;
    forecastVol: number;
    volScore: number;
    drawdown: number;
    ddScore: number;
    confirmedScore: number;
    confirmedTrendBreadth: number;
    confirmedVolScore: number;
    confirmedDDScore: number;
    confirmedEquityTarget: number;
    provisionalEquityTarget: number;
  };
  assets: PublicAsset[];
  history: Array<{ date: string; riskScore: number; targetEquity: number; drawdown: number }>;
  diagnostics: RiskDiagnostics;
  decisionLog: Array<{
    date: string;
    strategyVersion: string;
    configFingerprint: string;
    riskScore: number;
    riskRegime: string;
    equityTarget: number;
    targetWeights: Record<AssetCode, number>;
    trendScores?: Partial<Record<AssetCode, number>>;
    relativeStrength?: Partial<Record<AssetCode, number>>;
    volScore?: number;
    ddScore?: number;
    drawdown?: number;
    reason?: string;
  }>;
  backtest: {
    status: string;
    period: { start: string; end: string };
    costRate: number;
    riskFreeRate: number;
    executionAssumption: string;
    qdiiPremiumHistoryIncluded: boolean;
    strategies: Array<{ key: string; label: string; metrics: StrategyMetrics; nav: Array<{ date: string; value: number }> }>;
    robustness: {
      status: string;
      warning: boolean;
      passRate: number;
      minimumPassRate: number;
      cases: number;
      rule: string;
      walkForwardTestFolds: number;
      walkForward: {
        testFolds: number;
        positiveCagrRate: number | null;
        worstCagr: number | null;
        medianMaxDrawdown: number | null;
      };
      costStress: Array<{
        costBp: number;
        cases: number;
        medianCagr: number | null;
        medianMaxDrawdown: number | null;
        medianTurnover: number | null;
      }>;
      evidenceLevel: 'LIMITED' | 'MODERATE' | 'STRONG';
    };
  };
  policy: { priority: string[]; prohibited: string[]; adviceNature: string };
}

export interface LocalPortfolio {
  schemaVersion: 1;
  updatedAt: string;
  values: Record<AssetCode, number>;
  cash: number;
  qdiiPremium: number | null;
  qdiiPremiumUpdatedAt?: string | null;
  monthlyContribution?: number;
  householdPolicy?: {
    enabled: boolean;
    emergencyFundReady: boolean | null;
    householdEquityCap: number | null;
    liabilityEquityCap: number | null;
    horizonYears: number | null;
    maxTolerableDrawdown: number | null;
  };
}

export interface AdviceRow {
  code: AssetCode;
  currentWeight: number;
  targetWeight: number;
  gap: number;
  band: number;
  tradeWeight: number;
  suggestedAmount: number;
  suggestedShares: number;
  roundedAmount: number;
  roundingResidual: number;
  action: 'BUY' | 'SELL' | 'NO TRADE';
  reason: string;
}
