import type { AdviceRow, AssetCode, LocalPortfolio, PublicAsset, PublicSnapshot } from './types';
import { ASSET_CODES } from './types';

type ExecutionModel = PublicSnapshot['executionModel'];

export interface AdviceResult {
  available: boolean;
  adviceAllowed: boolean;
  blockedReason: string | null;
  totalValue: number;
  currentWeights: Record<AssetCode, number>;
  currentEquity: number;
  modelEquityTarget: number;
  operationalEquityTarget: number;
  cashWeight: number;
  targetCashWeight: number;
  premiumStatus: string;
  holdingsFresh: boolean;
  premiumFresh: boolean;
  contributionUsed: number;
  rows: AdviceRow[];
}

export function emptyPortfolio(): LocalPortfolio {
  return {
    schemaVersion: 1,
    updatedAt: new Date(0).toISOString(),
    values: { '512890': 0, '513100': 0, '588000': 0, '518880': 0, '511010': 0 },
    cash: 0,
    qdiiPremium: null,
    qdiiPremiumUpdatedAt: null,
    monthlyContribution: 0,
    householdPolicy: {
      enabled: false,
      emergencyFundReady: null,
      householdEquityCap: null,
      liabilityEquityCap: null,
      horizonYears: null,
      maxTolerableDrawdown: null,
    },
  };
}

function ageHours(value: string | null | undefined, now: Date): number {
  const parsed = value ? new Date(value).getTime() : Number.NaN;
  return Number.isFinite(parsed) ? Math.max(0, now.getTime() - parsed) / 3_600_000 : Number.POSITIVE_INFINITY;
}

function premiumStatus(premium: number | null, fresh: boolean, model: ExecutionModel): string {
  if (premium == null || !Number.isFinite(premium)) return '需要人工输入';
  if (!fresh) return '溢价已过期 · 禁止新增';
  if (premium >= model.premiumGate.redWarningThreshold) return 'RED WARNING';
  if (premium >= model.premiumGate.blockBuyThreshold) return '禁止新增买入';
  if (premium >= model.premiumGate.halfBuyThreshold) return `仅执行${Math.round(model.premiumGate.halfBuyFactor * 100)}%买入`;
  return '正常';
}

function operationalTargets(portfolio: LocalPortfolio, assets: PublicAsset[]): {
  targets: Record<AssetCode, number>;
  modelEquity: number;
  operationalEquity: number;
} {
  const targets = Object.fromEntries(assets.map((asset) => [asset.code, asset.confirmedTarget])) as Record<AssetCode, number>;
  const modelEquity = targets['512890'] + targets['513100'] + targets['588000'];
  const policy = portfolio.householdPolicy;
  if (!policy?.enabled) return { targets, modelEquity, operationalEquity: modelEquity };
  const validCaps = [policy.householdEquityCap, policy.liabilityEquityCap]
    .filter((value): value is number => value != null && Number.isFinite(value) && value >= 0);
  const operationalEquity = Math.min(modelEquity, ...validCaps);
  const scale = modelEquity > 0 ? operationalEquity / modelEquity : 1;
  (['512890', '513100', '588000'] as AssetCode[]).forEach((code) => { targets[code] *= scale; });
  return { targets, modelEquity, operationalEquity };
}

export function calculateAdvice(
  portfolio: LocalPortfolio,
  assets: PublicAsset[],
  model: ExecutionModel,
  health: Pick<PublicSnapshot['health'], 'blocking' | 'summary'> = { blocking: false, summary: '' },
  now = new Date(),
): AdviceResult {
  const invested = ASSET_CODES.reduce((total, code) => total + Math.max(0, portfolio.values[code] || 0), 0);
  const cash = Math.max(0, portfolio.cash || 0);
  const contribution = Math.max(0, portfolio.monthlyContribution || 0);
  const recordedValue = invested + cash;
  const totalValue = recordedValue + contribution;
  const available = recordedValue > 0;
  const holdingsFresh = ageHours(portfolio.updatedAt, now) <= model.freshness.holdingsMaxAgeDays * 24;
  const premiumFresh = ageHours(portfolio.qdiiPremiumUpdatedAt, now) <= model.freshness.premiumMaxAgeHours;
  const currentWeights = Object.fromEntries(ASSET_CODES.map((code) => [
    code, totalValue > 0 ? Math.max(0, portfolio.values[code] || 0) / totalValue : 0,
  ])) as Record<AssetCode, number>;
  const { targets: target, modelEquity, operationalEquity } = operationalTargets(portfolio, assets);
  const targetCashWeight = Math.max(0, 1 - ASSET_CODES.reduce((sum, code) => sum + (target[code] ?? 0), 0));
  const emergencyBlocked = portfolio.householdPolicy?.enabled && portfolio.householdPolicy.emergencyFundReady !== true;
  const blockedReason = health.blocking
    ? `数据闸门已关闭：${health.summary || '数据健康检查未通过'}`
    : !available
      ? '尚未录入本机持仓'
      : !holdingsFresh
        ? `持仓已超过 ${model.freshness.holdingsMaxAgeDays} 天未更新`
        : emergencyBlocked
          ? '家庭应急资金尚未确认准备完成，暂停新增投资建议'
          : null;
  const adviceAllowed = blockedReason == null;
  const gaps = Object.fromEntries(ASSET_CODES.map((code) => [code, (target[code] ?? 0) - currentWeights[code]])) as Record<AssetCode, number>;
  const bands = Object.fromEntries(ASSET_CODES.map((code) => [
    code, Math.max(model.rebalance.absoluteBand, model.rebalance.relativeBand * (target[code] ?? 0)),
  ])) as Record<AssetCode, number>;
  const deltas = Object.fromEntries(ASSET_CODES.map((code) => [
    code, adviceAllowed && Math.abs(gaps[code]) >= bands[code] ? model.rebalance.partialFactor * gaps[code] : 0,
  ])) as Record<AssetCode, number>;

  const buys = ASSET_CODES.reduce((sum, code) => sum + Math.max(0, deltas[code]), 0);
  const sells = ASSET_CODES.reduce((sum, code) => sum + Math.max(0, -deltas[code]), 0);
  const buyBudget = sells + (totalValue > 0 ? (cash + contribution) / totalValue : 0);
  if (buys > buyBudget && buys > 0) {
    const factor = buyBudget / buys;
    ASSET_CODES.forEach((code) => { if (deltas[code] > 0) deltas[code] *= factor; });
  } else if (sells > buys && sells > 0 && targetCashWeight === 0) {
    const factor = buys / sells;
    ASSET_CODES.forEach((code) => { if (deltas[code] < 0) deltas[code] *= factor; });
  }

  const originalQdiiBuy = Math.max(0, deltas['513100']);
  let qdiiFactor = 1;
  if (portfolio.qdiiPremium == null || !premiumFresh || portfolio.qdiiPremium >= model.premiumGate.blockBuyThreshold) qdiiFactor = 0;
  else if (portfolio.qdiiPremium >= model.premiumGate.halfBuyThreshold) qdiiFactor = model.premiumGate.halfBuyFactor;
  if (originalQdiiBuy > 0) {
    deltas['513100'] = originalQdiiBuy * qdiiFactor;
    deltas['511010'] += originalQdiiBuy - deltas['513100'];
  }

  const rows = ASSET_CODES.map((code): AdviceRow => {
    const tradeWeight = deltas[code];
    const asset = assets.find((item) => item.code === code);
    const suggestedAmount = tradeWeight * totalValue;
    const lotSize = asset?.lotSize || model.defaultLotSize;
    const price = asset?.latestPrice || 0;
    const shareMagnitude = price > 0 ? Math.floor(Math.abs(suggestedAmount) / price / lotSize) * lotSize : 0;
    const suggestedShares = Math.sign(suggestedAmount) * shareMagnitude;
    const roundedAmount = suggestedShares * price;
    let action: AdviceRow['action'] = 'NO TRADE';
    let reason = !adviceAllowed ? blockedReason ?? '执行输入不可用' : Math.abs(gaps[code]) < bands[code] ? '处于免交易区间内' : '受现金与自融资约束，当前不产生可执行建议';
    if (tradeWeight > 1e-10) { action = 'BUY'; reason = `按目标缺口的${Math.round(model.rebalance.partialFactor * 100)}%进行部分再平衡`; }
    if (tradeWeight < -1e-10) { action = 'SELL'; reason = `按目标缺口的${Math.round(model.rebalance.partialFactor * 100)}%进行部分再平衡`; }
    if (contribution > 0 && action === 'BUY') reason += '，并优先使用本月新增资金';
    if (code === '513100' && originalQdiiBuy > deltas[code]) reason = 'QDII溢价缺失、过期或超限，限制新增买入但不改变模型目标';
    if (code === '511010' && originalQdiiBuy - deltas['513100'] > 0) reason = '暂时承接被QDII溢价门控拦截的计划资金';
    return {
      code, currentWeight: currentWeights[code], targetWeight: target[code] ?? 0,
      gap: gaps[code], band: bands[code], tradeWeight, suggestedAmount,
      suggestedShares, roundedAmount, roundingResidual: suggestedAmount - roundedAmount,
      action, reason,
    };
  });
  return {
    available, adviceAllowed, blockedReason, totalValue, currentWeights,
    currentEquity: currentWeights['512890'] + currentWeights['513100'] + currentWeights['588000'],
    modelEquityTarget: modelEquity, operationalEquityTarget: operationalEquity,
    cashWeight: totalValue > 0 ? (cash + contribution) / totalValue : 0,
    targetCashWeight, premiumStatus: premiumStatus(portfolio.qdiiPremium, premiumFresh, model),
    holdingsFresh, premiumFresh, contributionUsed: contribution, rows,
  };
}
