import { escapeHtml, instrumentLabel } from './format';
import type { LocalPortfolio, PublicSnapshot } from './types';

export function portfolioDialog(snapshot: PublicSnapshot, portfolio: LocalPortfolio): string {
  const policy = portfolio.householdPolicy;
  return `<dialog id="portfolio-dialog"><form method="dialog" id="portfolio-form"><div class="dialog-head"><div><p class="eyebrow">PRIVATE · 仅当前浏览器</p><h2>本机持仓</h2></div><button type="button" data-close-dialog aria-label="关闭">×</button></div><p class="privacy">请输入每只 ETF 的当前市值，而不是份额。数据只保存在当前浏览器，不会随页面请求发送到 GitHub。</p>
    <div class="holding-fields">${snapshot.assets.map((asset) => `<label><span>${escapeHtml(instrumentLabel(asset.code, asset.name))}<small>${escapeHtml(asset.role)}</small></span><input name="${asset.code}" type="number" min="0" step="0.01" inputmode="decimal" value="${portfolio.values[asset.code] || ''}" placeholder="0.00"></label>`).join('')}
      <label><span>可用现金<small>用于自融资约束</small></span><input name="cash" type="number" min="0" step="0.01" inputmode="decimal" value="${portfolio.cash || ''}" placeholder="0.00"></label>
      <label><span>本月计划新增资金<small>优先补充低配资产</small></span><input name="monthlyContribution" type="number" min="0" step="0.01" inputmode="decimal" value="${portfolio.monthlyContribution || ''}" placeholder="0.00"></label>
      <label><span>513100 纳指ETF 当前溢价<small>输入百分数，例如 2.1；保存时记录时间</small></span><input name="premium" type="number" step="0.01" inputmode="decimal" value="${portfolio.qdiiPremium == null ? '' : portfolio.qdiiPremium * 100}" placeholder="缺失或过期时阻断新增买入"></label></div>
    <fieldset class="policy-fields"><legend>家庭投资政策层 · 可选</legend><label class="policy-toggle"><input name="policyEnabled" type="checkbox" ${policy?.enabled ? 'checked' : ''}><span>启用家庭约束<small>只能降低模型风险，不会提高权益目标</small></span></label><div class="holding-fields">
      <label><span>应急资金状态<small>未评估或未准备时暂停新增投资建议</small></span><select name="emergencyFundReady"><option value="" ${policy?.emergencyFundReady == null ? 'selected' : ''}>未评估</option><option value="yes" ${policy?.emergencyFundReady === true ? 'selected' : ''}>已准备</option><option value="no" ${policy?.emergencyFundReady === false ? 'selected' : ''}>尚未准备</option></select></label>
      <label><span>家庭权益上限<small>百分数，例如 70</small></span><input name="householdEquityCap" type="number" min="0" max="100" step="0.1" value="${policy?.householdEquityCap == null ? '' : policy.householdEquityCap * 100}" placeholder="不限制"></label>
      <label><span>近期负债约束上限<small>百分数，例如 60</small></span><input name="liabilityEquityCap" type="number" min="0" max="100" step="0.1" value="${policy?.liabilityEquityCap == null ? '' : policy.liabilityEquityCap * 100}" placeholder="不限制"></label>
      <label><span>投资期限<small>年，仅用于适配记录</small></span><input name="horizonYears" type="number" min="0" max="100" step="1" value="${policy?.horizonYears ?? ''}" placeholder="例如 10"></label>
      <label><span>最大可承受回撤<small>百分数，仅作家庭约束记录</small></span><input name="maxTolerableDrawdown" type="number" min="0" max="100" step="0.1" value="${policy?.maxTolerableDrawdown == null ? '' : policy.maxTolerableDrawdown * 100}" placeholder="例如 20"></label>
    </div></fieldset>
    <div class="backup"><div><h3>加密备份</h3><p>密码不会保存；忘记后无法恢复备份。</p></div><input class="visually-hidden" type="text" autocomplete="username" value="FRAIS-5 本机备份" tabindex="-1" aria-hidden="true"><input id="backup-password" type="password" minlength="8" autocomplete="new-password" placeholder="备份密码，至少 8 个字符"><div class="backup-actions"><button type="button" class="secondary" id="export-backup">导出加密文件</button><button type="button" class="secondary" id="import-backup">导入加密文件</button><input id="backup-file" type="file" accept="application/json,.json" hidden></div></div>
    <div id="dialog-status" class="dialog-status" aria-live="polite"></div><div class="dialog-actions"><button type="button" data-close-dialog class="secondary">取消</button><button type="submit" class="primary">${snapshot.health.blocking ? '仅保存本机持仓' : '保存并重新计算'}</button></div></form></dialog>`;
}
