import { escapeHtml, instrumentLabel, number, percent } from './format';
import type { AssetCode, MarketBar, MarketSeriesBundle, PublicSnapshot } from './types';

export type MarketRange = '6M' | '1Y' | '3Y';

const RANGE_DAYS: Record<MarketRange, number> = { '6M': 126, '1Y': 252, '3Y': 756 };
const VIEW_WIDTH = 1000;
const PLOT_LEFT = 54;
const PLOT_RIGHT = 982;
const PRICE_TOP = 34;
const PRICE_BOTTOM = 390;
const VOLUME_TOP = 446;
const VOLUME_BOTTOM = 566;

export function movingAverage(values: Array<number | null>, period: number): Array<number | null> {
  const result: Array<number | null> = [];
  let sum = 0;
  let valid = 0;
  for (let index = 0; index < values.length; index += 1) {
    const current = values[index];
    if (current != null && Number.isFinite(current)) { sum += current; valid += 1; }
    if (index >= period) {
      const expired = values[index - period];
      if (expired != null && Number.isFinite(expired)) { sum -= expired; valid -= 1; }
    }
    result.push(index >= period - 1 && valid === period ? sum / period : null);
  }
  return result;
}

export function windowedBars(bars: MarketBar[], range: MarketRange): MarketBar[] {
  return bars.slice(-RANGE_DAYS[range]);
}

export function rollingDrawdown(bars: MarketBar[], period = 252): number | null {
  if (!bars.length) return null;
  const recent = bars.slice(-period);
  const high = Math.max(...recent.map((bar) => bar.close));
  return high > 0 ? bars.at(-1)!.close / high - 1 : null;
}

function compact(value: number | null): string {
  if (value == null || !Number.isFinite(value)) return '—';
  if (Math.abs(value) >= 1e8) return `${number(value / 1e8, 2)}亿`;
  if (Math.abs(value) >= 1e4) return `${number(value / 1e4, 1)}万`;
  return number(value, 0);
}

function pathFor(values: Array<number | null>, x: (index: number) => number, y: (value: number) => number): string {
  let started = false;
  return values.map((value, index) => {
    if (value == null || !Number.isFinite(value)) { started = false; return ''; }
    const command = started ? 'L' : 'M';
    started = true;
    return `${command}${x(index).toFixed(2)},${y(value).toFixed(2)}`;
  }).join(' ');
}

function chartMarkup(bars: MarketBar[], allBars: MarketBar[], range: MarketRange, hasVolume: boolean): string {
  const closes = bars.map((bar) => bar.close);
  const allClose = allBars.map((bar) => bar.close);
  const start = Math.max(0, allBars.length - bars.length);
  const ma63 = movingAverage(allClose, 63).slice(start);
  const ma252 = movingAverage(allClose, 252).slice(start);
  const candidates = [...closes, ...ma63, ...ma252].filter((value): value is number => value != null && Number.isFinite(value));
  const rawMin = Math.min(...candidates);
  const rawMax = Math.max(...candidates);
  const padding = Math.max((rawMax - rawMin) * .1, rawMax * .01);
  const min = rawMin - padding;
  const max = rawMax + padding;
  const span = Math.max(max - min, .000001);
  const x = (index: number) => PLOT_LEFT + index / Math.max(1, bars.length - 1) * (PLOT_RIGHT - PLOT_LEFT);
  const y = (value: number) => PRICE_BOTTOM - (value - min) / span * (PRICE_BOTTOM - PRICE_TOP);
  const closePath = pathFor(closes, x, y);
  const ma63Path = pathFor(ma63, x, y);
  const ma252Path = pathFor(ma252, x, y);
  const area = closePath ? `${closePath} L${PLOT_RIGHT},${PRICE_BOTTOM} L${PLOT_LEFT},${PRICE_BOTTOM} Z` : '';
  const volumes = bars.map((bar) => bar.volume ?? 0);
  const volumeMax = Math.max(...volumes, 1);
  const barWidth = Math.max(.8, (PLOT_RIGHT - PLOT_LEFT) / Math.max(1, bars.length) * .72);
  const volumeBars = hasVolume ? bars.map((bar, index) => {
    const height = (bar.volume ?? 0) / volumeMax * (VOLUME_BOTTOM - VOLUME_TOP);
    const previous = index ? bars[index - 1]?.close ?? bar.close : bar.open ?? bar.close;
    const tone = bar.close >= previous ? 'up' : 'down';
    return `<rect class="volume-bar ${tone}" x="${(x(index) - barWidth / 2).toFixed(2)}" y="${(VOLUME_BOTTOM - height).toFixed(2)}" width="${barWidth.toFixed(2)}" height="${Math.max(height, .5).toFixed(2)}" />`;
  }).join('') : '';
  const grid = [0, .25, .5, .75, 1].map((ratio) => {
    const lineY = PRICE_TOP + ratio * (PRICE_BOTTOM - PRICE_TOP);
    const label = max - ratio * span;
    return `<line x1="${PLOT_LEFT}" y1="${lineY}" x2="${PLOT_RIGHT}" y2="${lineY}"/><text x="${PLOT_RIGHT}" y="${lineY - 7}">${number(label, label < 10 ? 3 : 2)}</text>`;
  }).join('');
  const axisDates = [0, Math.floor((bars.length - 1) / 2), bars.length - 1].map((index) => `<text class="axis-date" x="${x(index)}" y="594" text-anchor="${index === 0 ? 'start' : index === bars.length - 1 ? 'end' : 'middle'}">${escapeHtml(bars[index]?.date ?? '')}</text>`).join('');

  return `<div class="chart-legend"><span><i class="legend-price"></i>前复权收盘</span><span><i class="legend-ma63"></i>63日均线</span><span><i class="legend-ma252"></i>252日均线</span><span class="chart-range-label">${range} · ${bars.length} 个交易日</span></div>
    <div class="chart-canvas"><svg viewBox="0 0 ${VIEW_WIDTH} 610" role="img" tabindex="0" aria-label="ETF前复权价格、均线和成交量走势图。聚焦后可用左右方向键逐日查看，Home 和 End 跳到区间首尾。">
      <g class="chart-grid">${grid}</g>
      <path class="price-area" d="${area}" />
      <path class="ma-line ma252" d="${ma252Path}" />
      <path class="ma-line ma63" d="${ma63Path}" />
      <path class="price-line" d="${closePath}" />
      <line class="volume-divider" x1="${PLOT_LEFT}" y1="${VOLUME_TOP - 22}" x2="${PLOT_RIGHT}" y2="${VOLUME_TOP - 22}" />
      <text class="volume-label" x="${PLOT_LEFT}" y="${VOLUME_TOP - 30}">${hasVolume ? '成交量（手）' : '当前数据源未提供成交量'}</text>
      <g class="volume-bars">${volumeBars}</g>
      ${axisDates}
      <line class="chart-crosshair" x1="${PLOT_LEFT}" y1="${PRICE_TOP}" x2="${PLOT_LEFT}" y2="${VOLUME_BOTTOM}" />
    </svg><div class="market-tooltip" hidden></div></div>`;
}

function bindCrosshair(container: HTMLElement, bars: MarketBar[]): void {
  const svg = container.querySelector<SVGSVGElement>('svg');
  const crosshair = container.querySelector<SVGLineElement>('.chart-crosshair');
  const tooltip = container.querySelector<HTMLElement>('.market-tooltip');
  if (!svg || !crosshair || !tooltip || !bars.length) return;
  let activeIndex = bars.length - 1;
  const showIndex = (index: number) => {
    activeIndex = Math.max(0, Math.min(bars.length - 1, index));
    const ratio = activeIndex / Math.max(1, bars.length - 1);
    const bar = bars[activeIndex]!;
    const x = PLOT_LEFT + ratio * (PLOT_RIGHT - PLOT_LEFT);
    crosshair.setAttribute('x1', String(x));
    crosshair.setAttribute('x2', String(x));
    crosshair.classList.add('visible');
    tooltip.hidden = false;
    tooltip.style.left = `${Math.max(8, Math.min(78, ratio * 100))}%`;
    const dayChange = activeIndex ? bar.close / (bars[activeIndex - 1]?.close ?? bar.close) - 1 : 0;
    tooltip.innerHTML = `<strong>${escapeHtml(bar.date)}</strong><span>收盘 ${number(bar.close, 3)} · ${dayChange >= 0 ? '+' : ''}${percent(dayChange)}</span><span>开 / 高 / 低 ${number(bar.open, 3)} / ${number(bar.high, 3)} / ${number(bar.low, 3)}</span><span>成交量 ${compact(bar.volume)}</span>`;
  };
  const move = (event: PointerEvent) => {
    const rect = svg.getBoundingClientRect();
    const viewX = (event.clientX - rect.left) / rect.width * VIEW_WIDTH;
    const ratio = Math.max(0, Math.min(1, (viewX - PLOT_LEFT) / (PLOT_RIGHT - PLOT_LEFT)));
    const index = Math.round(ratio * Math.max(0, bars.length - 1));
    showIndex(index);
  };
  svg.addEventListener('pointermove', move);
  svg.addEventListener('pointerleave', () => {
    crosshair.classList.remove('visible');
    tooltip.hidden = true;
  });
  svg.addEventListener('focus', () => showIndex(activeIndex));
  svg.addEventListener('blur', () => {
    crosshair.classList.remove('visible');
    tooltip.hidden = true;
  });
  svg.addEventListener('keydown', (event) => {
    if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
    event.preventDefault();
    if (event.key === 'Home') showIndex(0);
    else if (event.key === 'End') showIndex(bars.length - 1);
    else showIndex(activeIndex + (event.key === 'ArrowLeft' ? -1 : 1));
  });
}

function renderWorkspace(bundle: MarketSeriesBundle, snapshot: PublicSnapshot, code: AssetCode, range: MarketRange): void {
  const market = bundle.assets[code];
  const asset = snapshot.assets.find((item) => item.code === code);
  const chart = document.querySelector<HTMLElement>('#market-chart');
  const metrics = document.querySelector<HTMLElement>('#market-metrics');
  const interpretation = document.querySelector<HTMLElement>('#market-interpretation');
  if (!market || !asset || !chart || !metrics || !interpretation) return;
  const bars = windowedBars(market.bars, range);
  const latest = bars.at(-1);
  if (!latest || !bars.length) {
    chart.innerHTML = '<p class="empty">当前标的没有可展示的市场序列。</p>';
    return;
  }
  const allClose = market.bars.map((bar) => bar.close);
  const ma63 = movingAverage(allClose, 63).at(-1);
  const ma252 = movingAverage(allClose, 252).at(-1);
  const startClose = bars[0]!.close;
  const rangeReturn = latest.close / startClose - 1;
  const volumes = market.bars.map((bar) => bar.volume);
  const volume20 = movingAverage(volumes, 20).at(-1);
  const volumeRatio = latest.volume != null && volume20 ? latest.volume / volume20 : null;
  const drawdown = rollingDrawdown(market.bars);
  const trendCopy = ma252 == null ? '长期均线历史不足' : latest.close >= ma252 ? '价格位于252日均线上方' : '价格位于252日均线下方';
  const volumeCopy = volumeRatio == null ? '量能数据暂不可用' : volumeRatio >= 1.3 ? '成交量明显高于20日均量' : volumeRatio <= .7 ? '成交量低于20日均量' : '成交量接近20日均量';

  metrics.innerHTML = `<div><span>最新前复权收盘</span><strong>${number(latest.close, 3)}</strong><small>${escapeHtml(latest.date)}</small></div><div><span>${range}区间收益</span><strong class="${rangeReturn >= 0 ? 'positive' : 'negative'}">${rangeReturn >= 0 ? '+' : ''}${percent(rangeReturn)}</strong><small>只描述已发生价格</small></div><div><span>距252日高点</span><strong>${percent(drawdown)}</strong><small>滚动252日口径</small></div><div><span>最新量 / 20日均量</span><strong>${volumeRatio == null ? '—' : `${number(volumeRatio, 2)}×`}</strong><small>${market.hasVolume ? '真实日成交量' : '数据源未提供'}</small></div>`;
  interpretation.innerHTML = `<p class="eyebrow">${escapeHtml(instrumentLabel(code, asset.name))}</p><h3>${escapeHtml(trendCopy)}</h3><p>${escapeHtml(volumeCopy)}。当前多周期趋势评分为 <strong>${number(asset.trendScore)}</strong>，预测波动率为 <strong>${percent(asset.forecastVol)}</strong>。</p><dl><div><dt>63日均线</dt><dd>${number(ma63, 3)}</dd></div><div><dt>252日均线</dt><dd>${number(ma252, 3)}</dd></div><div><dt>目标权重</dt><dd>${percent(asset.confirmedTarget)}</dd></div><div><dt>数据来源</dt><dd>${escapeHtml(market.source)}</dd></div></dl><small>成交量不进入 FRAIS V1 风险评分；它只用于核对价格变化是否伴随量能变化。</small>`;
  chart.classList.add('is-changing');
  chart.innerHTML = chartMarkup(bars, market.bars, range, market.hasVolume);
  bindCrosshair(chart, bars);
  requestAnimationFrame(() => chart.classList.remove('is-changing'));
  document.querySelectorAll<HTMLElement>('[data-market-code]').forEach((button) => button.setAttribute('aria-pressed', String(button.dataset.marketCode === code)));
  document.querySelectorAll<HTMLElement>('[data-market-range]').forEach((button) => button.setAttribute('aria-pressed', String(button.dataset.marketRange === range)));
}

export function bindMarketWorkspace(bundle: MarketSeriesBundle, snapshot: PublicSnapshot): void {
  let selected = snapshot.assets[0]?.code ?? '512890';
  let range: MarketRange = '1Y';
  document.querySelectorAll<HTMLElement>('[data-market-code]').forEach((button) => button.addEventListener('click', () => {
    selected = button.dataset.marketCode as AssetCode;
    renderWorkspace(bundle, snapshot, selected, range);
  }));
  document.querySelectorAll<HTMLElement>('[data-market-range]').forEach((button) => button.addEventListener('click', () => {
    range = button.dataset.marketRange as MarketRange;
    renderWorkspace(bundle, snapshot, selected, range);
  }));
  renderWorkspace(bundle, snapshot, selected, range);
}
