import { date, escapeHtml, instrumentLabel, money, number, percent } from './format';
import type { RenderedMarkdown } from './markdown';
import type { AdviceResult } from './rebalance';
import type { AssetCode, LocalPortfolio, MarketSeriesBundle, PublicAsset, PublicSnapshot } from './types';
import { REGIME, sparkline, type PageId } from './ui';

export interface PageContext {
  page: PageId;
  root: string;
  snapshot: PublicSnapshot;
  portfolio: LocalPortfolio;
  advice: AdviceResult;
  model?: RenderedMarkdown;
  market?: MarketSeriesBundle;
}

function signedPoints(value: number | null | undefined): string {
  if (value == null || !Number.isFinite(value)) return '—';
  return `${value > 0 ? '+' : ''}${number(value * 100, 1)} 个百分点`;
}

function labelForCode(snapshot: PublicSnapshot, code: string): string {
  const asset = snapshot.assets.find((candidate) => candidate.code === code);
  return instrumentLabel(code, asset?.name);
}

function previousConfirmedDecision(snapshot: PublicSnapshot): PublicSnapshot['decisionLog'][number] | undefined {
  for (let index = snapshot.decisionLog.length - 1; index >= 0; index -= 1) {
    if (snapshot.decisionLog[index]!.date < snapshot.meta.confirmedSignalDate) return snapshot.decisionLog[index];
  }
  return undefined;
}

function dataErrorBanner(context: PageContext): string {
  if (!context.snapshot.health.blocking) return '';
  return `<section class="data-error-banner" role="alert"><div><span>DATA ERROR</span><strong>新建议闸门已关闭</strong></div><p>${escapeHtml(context.snapshot.health.summary)}。以下仅保留 ${context.snapshot.meta.confirmedSignalDate} 月末确认的历史目标和本机持仓，不产生新买卖建议。</p><a href="${context.root}data/index.html">查看数据错误 →</a></section>`;
}

function riskContributionMarkup(snapshot: PublicSnapshot): string {
  const diagnostics = snapshot.diagnostics;
  const rows = diagnostics.riskContributions.map((item) => {
    const asset = snapshot.assets.find((candidate) => candidate.code === item.code);
    const capitalWidth = Math.min(100, Math.abs(item.weight) * 100);
    const riskWidth = Math.min(100, Math.abs(item.share) * 100);
    const riskLabel = item.share < 0 ? `抵消 ${percent(Math.abs(item.share))}` : percent(item.share);
    return `<div class="risk-owner"><span class="risk-owner-name"><strong>${escapeHtml(instrumentLabel(item.code, asset?.name))}</strong><small>${escapeHtml(asset?.role ?? '组合资产')}</small></span><div class="risk-owner-scales"><div><span>资金 ${percent(item.weight)}</span><i class="risk-owner-track capital"><b style="width:${capitalWidth}%"></b></i></div><div><span>风险 ${riskLabel}</span><i class="risk-owner-track risk ${item.share < 0 ? 'diversifier' : ''}"><b style="width:${riskWidth}%"></b></i></div></div><strong class="risk-owner-value ${item.share < 0 ? 'positive' : ''}">${riskLabel}</strong></div>`;
  }).join('');
  const largest = diagnostics.riskContributions.reduce((left, right) => left.share >= right.share ? left : right);
  const largestAsset = snapshot.assets.find((asset) => asset.code === largest.code);
  const dominant = diagnostics.riskContributions.filter((item) => item.share > 0).sort((left, right) => right.share - left.share).slice(0, 2);
  const dominantRisk = dominant.reduce((sum, item) => sum + item.share, 0);
  const dominantCapital = dominant.reduce((sum, item) => sum + item.weight, 0);
  const concentration = dominantRisk >= .8 ? '高度集中' : dominantRisk >= .65 ? '明显集中' : '相对分散';
  const dominantNames = dominant.map((item) => labelForCode(snapshot, item.code)).join(' 与 ');
  return `<div class="risk-concentration reveal"><div><span>${concentration}</span><strong>${escapeHtml(dominantNames)}合计承担 ${percent(dominantRisk)} 的组合风险</strong></div><p>两者合计资金占比为 ${percent(dominantCapital)}。当风险占比显著高于资金占比时，说明名义分散并未等比例转化为风险分散。</p><small>诊断只用于家庭复核，不改变 V1.1 目标权重</small></div><div class="risk-ownership reveal"><div class="risk-ownership-summary"><p class="eyebrow">RISK OWNERSHIP · ${diagnostics.windowDays}日</p><h3>${escapeHtml(instrumentLabel(largest.code, largestAsset?.name))}是当前最大风险来源</h3><p>资金占比不等于风险占比。这里把确认目标权重与截至 ${diagnostics.asOf} 的协方差结合，回答每只资产对组合波动贡献了多少。</p><dl><div><dt>组合年化波动</dt><dd>${percent(diagnostics.portfolioAnnualVolatility)}</dd></div><div><dt>权益内部平均相关</dt><dd>${number(diagnostics.averageEquityCorrelation)}</dd></div></dl></div><div class="risk-owner-list">${rows}</div></div><p class="method-note">风险贡献允许防御资产出现负值，代表其在该窗口内抵消了部分组合波动。该模块只解释确认目标，不改变任何目标权重。</p>`;
}

function narrative(snapshot: PublicSnapshot): string {
  if (snapshot.health.blocking) return '数据质量门槛未通过。系统保留上一份已确认方案，不生成新的人工再平衡建议。';
  const risk = snapshot.risk;
  const trend = risk.confirmedTrendBreadth >= .67 ? '确认日权益趋势整体有支撑' : risk.confirmedTrendBreadth >= .33 ? '确认日权益趋势出现分化' : '确认日多数权益趋势偏弱';
  const volatility = risk.confirmedVolScore >= .9 ? '波动压力较低' : risk.confirmedVolScore >= .65 ? '波动开始约束风险预算' : '波动压力显著';
  return `${trend}，${volatility}。模型把已确认权益目标控制在 ${percent(risk.confirmedEquityTarget)}；这是风险预算，不是涨跌预测。`;
}

function factor(title: string, weight: string, score: number, actual: string, meaning: string, implication: string): string {
  return `<article class="factor reveal"><span class="factor-index">${weight}</span><div><div class="factor-title"><h3>${title}</h3><strong>${actual}</strong></div><div class="factor-score"><span>模型评分 ${number(score * 100, 1)} / 100</span><div class="track"><i style="width:${Math.max(0, Math.min(100, score * 100))}%"></i></div></div></div><p>${meaning}<strong>${implication}</strong></p></article>`;
}

